import{_ as n,C as d,o as s,c,j as t,a as o,E as a,ag as l}from"./chunks/framework.HG0H2VLS.js";const x=JSON.parse('{"title":"FieldRow","description":"","frontmatter":{},"headers":[],"relativePath":"cc-components/field-row.md","filePath":"cc-components/field-row.md"}'),p={name:"cc-components/field-row.md"},h={id:"fieldrow",tabindex:"-1"};function g(m,e,u,f,b,y){const i=d("Badge"),r=d("ComponentDemo");return s(),c("div",null,[e[3]||(e[3]=t("hr",null,null,-1)),e[4]||(e[4]=t("h2",{id:"title-fieldrow",tabindex:"-1"},[o("title: FieldRow "),t("a",{class:"header-anchor",href:"#title-fieldrow","aria-label":'Permalink to "title: FieldRow"'},"​")],-1)),t("h1",h,[e[0]||(e[0]=o("FieldRow ",-1)),a(i,{type:"info",text:"Design System"}),e[1]||(e[1]=o()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#fieldrow","aria-label":'Permalink to "FieldRow <Badge type="info" text="Design System" />"'},"​",-1))]),e[5]||(e[5]=t("blockquote",null,[t("p",null,"Label + value for record screens: Wide (192px label) / Compact (128px sidebar term); view types Text, Tags, Paragraph, Media; edit types Input, Select, TagBox, Textarea, Media Picker with Required asterisk")],-1)),a(r,{src:"/demos/src/cc/components/FieldRow/FieldRow.html"}),e[6]||(e[6]=l('<h2 id="token-gaps-decisions" tabindex="-1">Token Gaps &amp; Decisions <a class="header-anchor" href="#token-gaps-decisions" aria-label="Permalink to &quot;Token Gaps &amp; Decisions&quot;">​</a></h2><p>Designer decisions 2026-09-28: label weight Medium (draft mixed Medium/SemiBold); label column <code>--ao-size-3</code> 192 (draft raw 200); values <code>--ao-text-primary</code> (draft <code>Dark Blue/800</code> primitive); row gap <code>--ao-spacing-5</code> (lives on RecordSection). Sidebar term column <code>--ao-size-1</code> is uniform across panels (draft sized per panel). Figma variant text is NOT a shared TEXT property — linked text syncs across variants.</p><h2 id="layout-stacked-2026-09-28" tabindex="-1">Layout=Stacked (2026-09-28) <a class="header-anchor" href="#layout-stacked-2026-09-28" aria-label="Permalink to &quot;Layout=Stacked (2026-09-28)&quot;">​</a></h2><p>Nine Figma variants (<code>3904:16242</code>… one per Wide Type): label over value, gap <code>spacing/3</code>, label padding 0, children fill. <strong>Not a class in code</strong> — it is what <code>@container record-section (max-width: 559px)</code> does to a Wide row (RecordSection.css). Media keeps MediaMeta&#39;s row (layout B needs no stacked form). Code Connect maps Stacked → no modifier.</p><h2 id="code-first-kinds-from-article-10007-2026-09-29-—-flag-for-figma" tabindex="-1">Code-first kinds from Article 10007 (2026-09-29) — FLAG FOR FIGMA <a class="header-anchor" href="#code-first-kinds-from-article-10007-2026-09-29-—-flag-for-figma" aria-label="Permalink to &quot;Code-first kinds from Article 10007 (2026-09-29) — FLAG FOR FIGMA&quot;">​</a></h2><p>Not in the Figma set yet; built to fill the framework with a real article (RecordScreen/record_10007.py): <code>Type=Rich</code> (view <code>.field-row__rich</code> — h2 <code>fixed-sm</code> / h3 <code>fixed-xs</code> semibold, blockquote 2px <code>--ao-border-brand</code> left rule + <code>spacing-4</code> inset, blocks <code>spacing-4</code> apart), <code>Type=Checkbox</code> (<code>.field-row--check</code>, label padding 0, centred), <code>Type=Date / Datetime</code> (DatePicker field), <code>Type=Lookup</code> (<code>.field-row__lookup</code>: input + Secondary Select, gap <code>spacing-3</code>), <code>Type=Image</code> (<code>.field-row__image</code>: MediaPicker then <code>.field-row__image-options</code> grid of Alt text / Caption / Alignment radios / Width select, gap <code>spacing-4</code>), <code>Type=File</code> (MediaPicker with a file icon + Choose file). Every value is an existing token; the arrangements are proposals for the designer.</p><h2 id="image-options-layout-designer-2026-09-29" tabindex="-1">Image options layout (designer, 2026-09-29) <a class="header-anchor" href="#image-options-layout-designer-2026-09-29" aria-label="Permalink to &quot;Image options layout (designer, 2026-09-29)&quot;">​</a></h2><p><code>.field-row__image-options</code> is <strong>1 column by default</strong> and <strong>2 columns</strong> (Alt text | Caption, then Alignment | Width) at <code>@container field-image (min-width: 560px)</code>. <code>.field-row__image</code> is its own container, because the record&#39;s value column, not the section, decides the fit: at a 1459 viewport the section is about 1000 but the value column is about 400. Keying on the section gave 175px cells and overlapping Alignment segments (designer screenshot, 2026-09-29). Alignment (<code>field-align</code> container, content-box thresholds) tightens its segments below 270 and goes icon-only below 222, keeping each label visually hidden so every radio still has a name. <strong>Alignment is a SegmentedControl</strong> (<code>.seg-control.field-row__align</code>, <code>data-seg-control</code>) with icon + text: <code>align-left</code> / <code>align-center</code> / <code>align-right</code> plus Left / Center / Right. It replaced three radios (designer, 2026-09-29) and is the editor-standard alignment control. At 40px (<code>--ao-spacing-8</code>) it sits level with Width without any centring rule. It is still a radiogroup for assistive tech (roving tabindex, arrow keys). <strong>Code-first: Figma still draws radios, so flag it for Figma.</strong></p><p>The <strong>thumbnail</strong> kind (<code>alt_only</code>, i.e. a field with no alignment or width: Thumbnail and Alternative Thumbnail) shows <strong>Alt text only</strong>, in <code>.field-row__image-options--single</code>, which is always one column. Content images (Main Image, Intro, Image Top, Image 1/2) keep all four options (designer, 2026-09-29).</p><h2 id="figma-build-2026-09-30-—-code-first-edit-kinds-drawn" tabindex="-1">Figma build 2026-09-30 — code-first edit kinds drawn <a class="header-anchor" href="#figma-build-2026-09-30-—-code-first-edit-kinds-drawn" aria-label="Permalink to &quot;Figma build 2026-09-30 — code-first edit kinds drawn&quot;">​</a></h2><p>Set <code>3861:1987</code> gains, for Layout=Wide and Stacked: Type=<strong>Lookup</strong> (<code>3931:19293</code> / <code>3931:19637</code>), <strong>Checkbox</strong> (<code>3931:19333</code> / <code>3931:19674</code>), <strong>Date</strong>, <strong>Datetime</strong>, <strong>Image</strong> (MediaPicker + Alt text / Caption / Alignment SegmentedControl / Width select; 2 columns Wide, 1 Stacked), <strong>Multimedia</strong>, <strong>Colour</strong> (ColorPickerInput). Rich text is still a Textarea in Figma (RichTextEditor not built yet). Labels: SemiBold + text-primary on every non-Compact row; they wrap (hug + max-width, the * stays beside the text). The Required * visibility had to be relinked on the cloned rows (clone drops property refs).</p><h2 id="collapsible-long-values-—-code-first-2026-10-09-not-in-figma" tabindex="-1">Collapsible long values — code-first (2026-10-09), NOT in Figma <a class="header-anchor" href="#collapsible-long-values-—-code-first-2026-10-09-not-in-figma" aria-label="Permalink to &quot;Collapsible long values — code-first (2026-10-09), NOT in Figma&quot;">​</a></h2><p>Asked by Luismi: article 245&#39;s Summary filled a screen and a half on the View. Mark&#39;s decisions:</p><table tabindex="0"><thead><tr><th>Rule</th><th>Value</th></tr></thead><tbody><tr><td>Which rows</td><td>every Wide view row of Type=Paragraph (Summary, Teaser, Page Description, custom text) and Type=Rich (Main Body, Introduction…). Not Compact (sidebar), not Edit, not Media.</td></tr><tr><td>When</td><td>Paragraph after <strong>6 lines</strong>, Rich after <strong>12</strong> (× <code>--ao-leading-md</code>). Only when the text really runs past the limit; short values are unchanged and get no button.</td></tr><tr><td>Collapsed look</td><td>capped height, the last line faded (two lines for Rich, whose cut can land in a paragraph gap). The fade is an alpha <code>mask-image</code> (<code>currentColor</code> → <code>transparent</code>), so it needs no gradient colour token and works on any surface.</td></tr><tr><td>Toggle</td><td>Button Secondary xs (as &quot;Image details&quot;), <code>--ao-spacing-3</code> above it: <code>chevron-down</code> &quot;Show more&quot; ⇄ &quot;Show less&quot; (the chevron rotates), <code>aria-expanded</code>.</td></tr><tr><td>Memory</td><td>none: every value starts collapsed.</td></tr></tbody></table><p><code>FieldRow.js</code> enhances the server-rendered markup: it wraps the value in <code>.field-row__clamp-body</code>, appends <code>.field-row__clamp-toggle</code>, sets <code>data-clamped</code> when the value is long and <code>data-expanded</code> when open, and re-measures with a <code>ResizeObserver</code> (the column changes width with no window resize). <code>window.fieldRowClamp.init(root)</code> for content added later. Loaded by every RecordScreen page (<code>_generate.py</code> KIT_JS).</p><p><strong>Figma push pending:</strong> a FieldRow Collapsed / Expanded state for Paragraph and Rich.</p><h2 id="variants" tabindex="-1">Variants <a class="header-anchor" href="#variants" aria-label="Permalink to &quot;Variants&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Node</th><th>Variant</th><th>Notes</th></tr></thead><tbody><tr><td><code>3861:1935</code></td><td>Layout=Wide, Type=Text</td><td></td></tr><tr><td><code>3861:1939</code></td><td>Layout=Wide, Type=Tags</td><td>Button Tertiary xs chips</td></tr><tr><td><code>3861:1967</code></td><td>Layout=Wide, Type=Paragraph</td><td>top-aligned</td></tr><tr><td><code>3861:1971</code></td><td>Layout=Wide, Type=Media</td><td>MediaMeta</td></tr><tr><td><code>3861:1987</code></td><td>Layout=Compact, Type=Text</td><td>sidebar</td></tr><tr><td><code>3861:1987</code></td><td>Layout=Compact, Type=Tags</td><td>sidebar</td></tr><tr><td><code>3861:1987</code></td><td>Layout=Wide, Type=Input</td><td>Input (Show Label off; help text = Input help)</td></tr><tr><td><code>3861:1987</code></td><td>Layout=Wide, Type=Select</td><td>Select (label hidden)</td></tr><tr><td><code>3861:1987</code></td><td>Layout=Wide, Type=TagBox</td><td>TagBox</td></tr><tr><td><code>3861:1987</code></td><td>Layout=Wide, Type=Textarea</td><td>Textarea</td></tr><tr><td><code>3861:1987</code></td><td>Layout=Wide, Type=Media Picker</td><td>MediaPicker</td></tr></tbody></table><h2 id="css-classes" tabindex="-1">CSS Classes <a class="header-anchor" href="#css-classes" aria-label="Permalink to &quot;CSS Classes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Figma</th><th>CSS</th></tr></thead><tbody><tr><td>Row</td><td><code>.field-row (+ --compact, --paragraph, --media, --edit)</code></td></tr><tr><td>Label</td><td><code>.field-row__label (dt / label / span)</code></td></tr><tr><td>Value</td><td><code>.field-row__value (dd / div)</code></td></tr><tr><td>Tags</td><td><code>.field-row__tags</code></td></tr><tr><td>Required (property)</td><td><code>.field-row__required (red *)</code></td></tr></tbody></table><h2 id="token-mapping" tabindex="-1">Token Mapping <a class="header-anchor" href="#token-mapping" aria-label="Permalink to &quot;Token Mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Token</th></tr></thead><tbody><tr><td>label column</td><td>--ao-size-3 (192) Wide · --ao-size-1 (128) Compact</td></tr><tr><td>gap</td><td>--ao-spacing-5 Wide · --ao-spacing-4 Compact</td></tr><tr><td>label</td><td>--ao-font-fixed-xs SemiBold (designer amend 2026-09-29, was Medium — flag for Figma) --ao-leading-sm --ao-text-primary (amend 2026-09-29, was text-secondary) --ao-tracking-4</td></tr><tr><td>value</td><td>--ao-font-fixed-xs Regular --ao-leading-md --ao-text-primary</td></tr><tr><td>compact text</td><td>--ao-font-fixed-xxs --ao-leading-xs (term --ao-text-contrast)</td></tr><tr><td>edit label offset</td><td>padding-top --ao-spacing-4 (centres on the 40px control)</td></tr><tr><td>required</td><td>--ao-text-error</td></tr><tr><td>tags gap</td><td>--ao-spacing-2</td></tr></tbody></table><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>Built 2026-09-28 from the View &amp; Edit kit (section <code>3861:1902</code>, CC Light mode). The kit was componentised from a code-capture draft that re-tokenise had bound to random / borrowed tokens; the designer ruled &quot;your recommendations are the way to go&quot;, so bindings were normalised to the right semantic tokens in Figma first and this code follows the kit, not the draft.</li><li>Markup comes from <code>src/cc/templates/RecordScreen/record_markup.py</code> — the demo and the templates are generated from the same function, so they cannot drift.</li></ul><h2 id="figma" tabindex="-1">Figma <a class="header-anchor" href="#figma" aria-label="Permalink to &quot;Figma&quot;">​</a></h2><p><a href="https://www.figma.com/design/Lus07xi8pPXLN87sQIyrEt/Affino---Design-System?node-id=3861-1987" target="_blank" rel="noreferrer">Open in Figma</a></p>',26))])}const k=n(p,[["render",g]]);export{x as __pageData,k as default};
